    SELECT
        'PCNT'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RCRT_PSNCNT_NO), LENGTH('PCNT' ) + 1)), 0) + 1, 6, '0')
    FROM PRJ_RCRT_PSNCNT
    WHERE PRJ_ANNC_NO = #{prjAnncNo}


